import{af as a,z as s,J as t,ab as r}from"./chunks/framework.plagcClB.js";const u=JSON.parse('{"title":"Responses and acknowledgments","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"devices/api/protocol/responses.md","filePath":"devices/api/protocol/responses.md"}'),n={name:"devices/api/protocol/responses.md"};function o(i,e,d,l,p,h){return s(),t("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1794479308000"},[...e[0]||(e[0]=[r('<h1 id="responses-and-acknowledgments" tabindex="-1">Responses and acknowledgments <a class="header-anchor" href="#responses-and-acknowledgments" aria-label="Permalink to &quot;Responses and acknowledgments&quot;">​</a></h1><p>A request and its reply are separate frames, with separate headers and data fields. The operation&#39;s message page defines the reply type, payload and errors. This page explains the shared conventions; it does not mean every request receives the same kind of reply.</p><h2 id="message-ids" tabindex="-1">Message IDs <a class="header-anchor" href="#message-ids" aria-label="Permalink to &quot;Message IDs&quot;">​</a></h2><p><a href="./headers#1-message-id">Message ID (header 1)</a> is a shared optional header for requests, responses, publications and message tracing. Individual implementations, transports or client services can impose additional requirements. Send helpers may add an ID automatically; that is not a requirement to serialize one in every frame.</p><ul><li>On a request, use a nonzero ID when acknowledgment or reply correlation is needed.</li><li>On a response, an optional Message ID identifies the response itself. It is independent of <a href="./headers#3-response-to">Response to (header 3)</a>, which identifies the original request.</li></ul><h2 id="correlating-a-reply" tabindex="-1">Correlating a reply <a class="header-anchor" href="#correlating-a-reply" aria-label="Permalink to &quot;Correlating a reply&quot;">​</a></h2><p>Include a nonzero <a href="./headers#1-message-id">Message ID (header 1)</a> when you need to match replies to requests. A correlated reply carries that ID in <a href="./headers#3-response-to">Response to (header 3)</a>.</p><h2 id="typed-responses-and-acks" tabindex="-1">Typed responses and ACKs <a class="header-anchor" href="#typed-responses-and-acks" aria-label="Permalink to &quot;Typed responses and ACKs&quot;">​</a></h2><p>Replies can take these forms:</p><ul><li>A typed response containing the requested data or result. Its message type is defined by the operation and need not always match the request type.</li><li>An <a href="./../messages/5-ack">ACK (MT5)</a>, which reports the command result without implying that a message-specific data payload was returned.</li></ul><p>An operation can send an interim ACK and a later typed result. Some targets also send a transport ACK alongside a typed response. An immediate typed response can replace a separate success ACK.</p><p>An ACK can identify the original request through Response to and/or its <strong>ACK Type data field (field 1)</strong>. ACK Type is the original message <strong>type</strong>, not the request&#39;s Message ID. See the <a href="./../messages/5-ack#header">MT5 packet format</a> for its full schema.</p><h3 id="when-an-ack-is-sent" tabindex="-1">When an ACK is sent <a class="header-anchor" href="#when-an-ack-is-sent" aria-label="Permalink to &quot;When an ACK is sent&quot;">​</a></h3><p>Whether an ACK is sent depends on the operation and target, but generally speaking any message with an ID should be acked. A missing or zero Message ID does not guarantee silence: typed replies and error replies may still be sent. Follow the message page&#39;s documented behavior.</p><h2 id="status-and-errors" tabindex="-1">Status and errors <a class="header-anchor" href="#status-and-errors" aria-label="Permalink to &quot;Status and errors&quot;">​</a></h2><p><a href="./headers#4-status">Status (header 4)</a> indicates a general reply status.</p><ul><li>Omitted Status means OK.</li><li><code>0</code> means OK.</li><li>Positive values indicate a non-OK result; some are retryable rather than terminal. The operation page explains the relevant causes.</li><li><code>-1</code> means Processing, with further responses expected. A nonpositive value does not necessarily mean the operation has finished.</li></ul><p>An unsuccessful command can use a different reply type from a successful one.</p><h2 id="subscription-replies-and-later-updates" tabindex="-1">Subscription replies and later updates <a class="header-anchor" href="#subscription-replies-and-later-updates" aria-label="Permalink to &quot;Subscription replies and later updates&quot;">​</a></h2><p>A subscription&#39;s control reply and its later publications are different events. A control ACK reports the command status; it is not the subscribed data. Later publications can have their own headers, payload and status behavior.</p><p>For Message Box, SUBSCRIBE/UNSUBSCRIBE use control ACKs. Later MT58 cache publications are distinct from terminal subscription status messages: expiry or abandonment can be reported without a cache payload or Message Version header. Tracking-session uploads are a separate device-to-server context. See <a href="./../messages/58-message-box#message-58-operation-subscribe">Message Box SUBSCRIBE</a> and the <a href="./../subscriptions/">subscription reference</a> for the applicable rules.</p>',21)])])}const m=a(n,[["render",o]]);export{u as __pageData,m as default};
